"""The corpus pages are generated by corpus/render.py from the results and AMENDMENTS.md. A paragraph written by hand
into a generated part of a page is silently dropped by the next render, so the committed pages must be exactly
what a render produces now: text that belongs there goes into AMENDMENTS.md, which the renderer reads."""
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
GENERATED = ["corpus/RESULTS.md", "corpus/v2/RESULTS.md", "website/docs/corpus.md"]


def test_committed_corpus_pages_are_what_render_writes(tmp_path):
    shutil.copytree(ROOT / "corpus", tmp_path / "corpus", ignore=shutil.ignore_patterns("__pycache__"))
    (tmp_path / "website" / "docs").mkdir(parents=True)
    shutil.copy2(ROOT / "website" / "docs" / "corpus.md", tmp_path / "website" / "docs" / "corpus.md")
    shutil.copytree(ROOT / "website" / "docs" / "corpus", tmp_path / "website" / "docs" / "corpus")
    for args in ([], ["--corpus", "v2"]):
        subprocess.run([sys.executable, str(tmp_path / "corpus" / "render.py"), *args], cwd=tmp_path, check=True,
                       capture_output=True)
    pages = GENERATED + [f"website/docs/corpus/{p.name}" for p in sorted((ROOT / "website/docs/corpus").glob("*.md"))]
    stale = [p for p in pages
             if (tmp_path / p).read_text(encoding="utf-8") != (ROOT / p).read_text(encoding="utf-8")]
    assert not stale, f"render.py would change {stale}: edit AMENDMENTS.md or the results, then rerun render.py"
